<script setup>import{Head,Link}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';defineProps({incidents:Object,filter:String});</script><template><Head title="Incidents"/><AuthenticatedLayout><template #header><div><h1 class="text-lg font-semibold text-white">Downtime incidents</h1><p class="text-xs text-slate-500">Outage and recovery record</p></div></template><div class="overflow-hidden rounded-xl border border-slate-800 bg-slate-900"><div v-for="i in incidents.data" class="grid gap-2 border-b border-slate-800 p-5 sm:grid-cols-4"><div><Link :href="route('hosts.show',i.host.id)" class="font-semibold text-white">{{i.host.name}}</Link><div class="font-mono text-xs text-slate-500">{{i.host.ip_address}}</div></div><div><span :class="i.status==='open'?'status-red':'status-emerald'" class="status-pill"><i></i>{{i.status}}</span></div><div class="text-sm"><div>{{new Date(i.started_at).toLocaleString()}}</div><div class="text-xs text-slate-500">Started</div></div><div class="text-sm"><div>{{i.recovered_at?new Date(i.recovered_at).toLocaleString():'Ongoing'}}</div><div class="text-xs text-slate-500">{{i.duration_seconds?Math.round(i.duration_seconds/60)+' minutes':'Duration'}}</div></div></div><div v-if="!incidents.data.length" class="p-16 text-center text-slate-500">No incidents recorded.</div></div></AuthenticatedLayout></template>
